 "content": "from collections import deque


def transform(grid):
    """Fill each hollow rectangular frame according to its hole's parity."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for yy, xx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy, xx))
                        q.append((yy, xx))
            r0 = min(y for y, _ in comp)
            r1 = max(y for y, _ in comp)
            c0 = min(x for _, x in comp)
            c1 = max(x for _, x in comp)
            ih, iw = r1 - r0 - 1, c1 - c0 - 1
            if ih < 1 or iw < 1:
                continue
            # A frame is exactly the complete one-cell-thick rectangular border.
            border = {(y, x) for y in range(r0, r1 + 1) for x in range(c0, c1 + 1)
                      if y in (r0, r1) or x in (c0, c1)}
            if set(comp) != border:
                continue
            fill = 7 if ih % 2 == 1 and iw % 2 == 1 else 2
            for y in range(r0 + 1, r1):
                for x in range(c0 + 1, c1):
                    out[y][x] = fill
    return out


if __name__ == "__main__":
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
